<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import type { LookupItem,TourServiceCommand,TourServiceDto } from '@/api/contracts'
import { loadLookup,tourServicesApi } from '@/api/resources'
import TourHotelsEditor from './TourHotelsEditor.vue'
import TourFlightsEditor from './TourFlightsEditor.vue'
import TourBusTransferEditor from './TourBusTransferEditor.vue'
import TourRailwayTransferEditor from './TourRailwayTransferEditor.vue'
import RemoteLookup from '@/components/RemoteLookup.vue'
const props=defineProps<{tourId:number}>(),emit=defineEmits<{tourChanged:[]}>()
const services=ref<TourServiceDto[]>([]),serviceTypes=ref<LookupItem[]>([]),error=ref(''),loading=ref(false),hotelService=ref<TourServiceDto>(),flightService=ref<TourServiceDto>(),busTransferService=ref<TourServiceDto>(),railwayTransferService=ref<TourServiceDto>(),savingServiceId=ref<number>(),draggedId=ref<number>(),dragOverId=ref<number>(),addMenuOpen=ref(false),addTypeId=ref<number|null>(null),adding=ref(false),renameService=ref<TourServiceDto>(),renameName=ref(''),renameSaving=ref(false),deleteService=ref<TourServiceDto>(),deleting=ref(false)
const deleteChildren=computed(()=>deleteService.value?services.value.filter(service=>service.ParentServiceId===deleteService.value?.Id):[])
async function load(){loading.value=true;try{services.value=await tourServicesApi.list(props.tourId)}catch(e){error.value=e instanceof Error?e.message:'Ошибка загрузки'}finally{loading.value=false}}
function specialized(typeId:number){return typeId===1||typeId===3}
function command(source:TourServiceCommand|TourServiceDto):TourServiceCommand{const fixed=specialized(source.ServiceTypeId);return{ServiceTypeId:source.ServiceTypeId,Name:source.Name,ParentServiceId:source.ParentServiceId??null,IsHidden:fixed?false:source.IsHidden,IsRemovable:fixed?false:source.IsRemovable,IsOptional:fixed?false:source.IsOptional}}
async function move(index:number,delta:number){const next=index+delta;if(next<0||next>=services.value.length)return;const copy=[...services.value];const a=copy[index],b=copy[next];if(!a||!b)return;copy[index]=b;copy[next]=a;try{services.value=await tourServicesApi.reorder(props.tourId,copy.map(x=>x.Id));emit('tourChanged')}catch(e){error.value=e instanceof Error?e.message:'Ошибка изменения порядка';await load()}}
async function quickAdd(typeId:number){if(adding.value)return;const type=serviceTypes.value.find(item=>item.Id===typeId);if(!type)return;adding.value=true;error.value='';try{await tourServicesApi.create(props.tourId,{ServiceTypeId:type.Id,Name:type.Name,ParentServiceId:null,IsHidden:false,IsRemovable:false,IsOptional:false});addMenuOpen.value=false;await load();emit('tourChanged')}catch(e){error.value=e instanceof Error?e.message:'Ошибка добавления услуги'}finally{adding.value=false;addTypeId.value=null}}
function openRename(service:TourServiceDto){renameService.value=service;renameName.value=service.Name}
async function saveRename(){const service=renameService.value;if(!service||!renameName.value.trim())return;renameSaving.value=true;error.value='';try{const updated=await tourServicesApi.update(props.tourId,service.Id,{...command(service),Name:renameName.value.trim()});const index=services.value.findIndex(item=>item.Id===service.Id);if(index>=0)services.value[index]=updated;renameService.value=undefined;emit('tourChanged')}catch(e){error.value=e instanceof Error?e.message:'Ошибка переименования услуги'}finally{renameSaving.value=false}}
async function removeService(){const service=deleteService.value;if(!service||deleteChildren.value.length)return;deleting.value=true;error.value='';try{await tourServicesApi.remove(props.tourId,service.Id);deleteService.value=undefined;await load();emit('tourChanged')}catch(e){error.value=e instanceof Error?e.message:'Ошибка удаления услуги'}finally{deleting.value=false}}
async function changeFlag(service:TourServiceDto,field:'IsHidden'|'IsRemovable'|'IsOptional',checked:boolean){if(specialized(service.ServiceTypeId))return;const value=command(service);value[field]=checked;if(field==='IsHidden'&&checked){value.IsRemovable=false;value.IsOptional=false}else if(checked){value.IsHidden=false}savingServiceId.value=service.Id;error.value='';try{const updated=await tourServicesApi.update(props.tourId,service.Id,value);const index=services.value.findIndex(x=>x.Id===service.Id);if(index>=0)services.value[index]=updated;emit('tourChanged')}catch(e){error.value=e instanceof Error?e.message:'Ошибка изменения параметров услуги'}finally{savingServiceId.value=undefined}}
function dragStart(event:DragEvent,service:TourServiceDto){draggedId.value=service.Id;event.dataTransfer?.setData('text/plain',String(service.Id));if(event.dataTransfer)event.dataTransfer.effectAllowed='move'}
async function drop(target:TourServiceDto){const sourceIndex=services.value.findIndex(x=>x.Id===draggedId.value),targetIndex=services.value.findIndex(x=>x.Id===target.Id);dragOverId.value=undefined;if(sourceIndex<0||targetIndex<0||sourceIndex===targetIndex)return;const copy=[...services.value],moved=copy.splice(sourceIndex,1)[0];if(!moved)return;copy.splice(targetIndex,0,moved);services.value=copy;try{services.value=await tourServicesApi.reorder(props.tourId,copy.map(x=>x.Id));emit('tourChanged')}catch(e){error.value=e instanceof Error?e.message:'Ошибка изменения порядка';await load()}finally{draggedId.value=undefined}}
watch(addTypeId,typeId=>{if(typeId)void quickAdd(typeId)})
onMounted(async()=>{await Promise.all([load(),loadLookup('/api/v1/services/service-types').then(items=>serviceTypes.value=items)])})
</script>
<template>
 <div>
  <div v-if="error" class="error-box">{{error}}</div>
  <div class="page-heading compact"><div><h3>Состав тура</h3><p>Услуги выполняются в указанном порядке.</p></div><div class="add-service"><button class="primary" :disabled="adding" @click="addMenuOpen=!addMenuOpen">{{adding?'Добавление…':'+ Добавить услугу'}} <span>⌄</span></button><div v-if="addMenuOpen" class="add-service-menu"><label>Выберите вид услуги</label><RemoteLookup v-model="addTypeId" endpoint="/api/v1/services/service-types" :nullable="false" placeholder="Начните вводить название" /><small>Услуга будет добавлена в конец состава.</small></div></div></div>
  <div class="service-columns"><span>Услуга</span><span>Скрытая</span><span>Удаляемая</span><span>Опциональная</span><span>Действия</span></div>
  <div class="service-list">
   <p v-if="loading" class="muted">Загрузка…</p><p v-else-if="!services.length" class="muted">В туре пока нет услуг.</p>
   <div v-for="(service,index) in services" :key="service.Id" class="service-card" :class="{dragging:draggedId===service.Id,'drag-over':dragOverId===service.Id}" @dragover.prevent="dragOverId=service.Id" @dragleave="dragOverId=undefined" @drop.prevent="drop(service)">
    <button class="drag-handle" draggable="true" title="Перетащить услугу" @dragstart="dragStart($event,service)" @dragend="draggedId=undefined;dragOverId=undefined">⋮⋮</button>
    <div class="service-name"><strong>{{index+1}}. {{service.Name}}</strong><div class="muted">Revision r{{service.Revision}}</div></div>
    <label class="inline-check" :title="specialized(service.ServiceTypeId)?'Для авиаперелёта и проживания параметр зафиксирован':''"><input type="checkbox" :checked="!specialized(service.ServiceTypeId)&&service.IsHidden" :disabled="specialized(service.ServiceTypeId)||savingServiceId===service.Id" @change="changeFlag(service,'IsHidden',($event.target as HTMLInputElement).checked)" /><span>Скрытая</span></label>
    <label class="inline-check" :title="specialized(service.ServiceTypeId)?'Для авиаперелёта и проживания параметр зафиксирован':''"><input type="checkbox" :checked="!specialized(service.ServiceTypeId)&&service.IsRemovable" :disabled="specialized(service.ServiceTypeId)||savingServiceId===service.Id" @change="changeFlag(service,'IsRemovable',($event.target as HTMLInputElement).checked)" /><span>Удаляемая</span></label>
    <label class="inline-check" :title="specialized(service.ServiceTypeId)?'Для авиаперелёта и проживания параметр зафиксирован':''"><input type="checkbox" :checked="!specialized(service.ServiceTypeId)&&service.IsOptional" :disabled="specialized(service.ServiceTypeId)||savingServiceId===service.Id" @change="changeFlag(service,'IsOptional',($event.target as HTMLInputElement).checked)" /><span>Опциональная</span></label>
    <div class="row-actions"><button v-if="service.ServiceTypeId===1" class="secondary" @click="flightService=service">Авиаперелёт</button><button v-if="service.ServiceTypeId===3" class="secondary" @click="hotelService=service">Проживание</button><button v-if="service.ServiceTypeId===14" class="secondary" @click="busTransferService=service">Автобусный переезд</button><button v-if="service.ServiceTypeId===15" class="secondary" @click="railwayTransferService=service">ЖД-переезд</button><button class="secondary" @click="openRename(service)">Переименовать</button><button class="danger" @click="deleteService=service">Удалить</button></div>
   </div>
  </div>
  <div v-if="renameService" class="rename-backdrop" @click.self="renameService=undefined"><form class="rename-dialog" @submit.prevent="saveRename"><div class="rename-header"><div><p class="eyebrow">Услуга</p><h3>Изменить название</h3></div><button type="button" class="secondary" @click="renameService=undefined">Закрыть</button></div><div class="field"><label>Название услуги</label><input v-model="renameName" autofocus required maxlength="256" /></div><div class="actions"><button class="primary" :disabled="renameSaving">{{renameSaving?'Сохранение…':'Сохранить'}}</button></div></form></div>
  <div v-if="deleteService" class="rename-backdrop" @click.self="!deleting&&(deleteService=undefined)"><section class="delete-dialog"><div class="delete-icon">!</div><h3>Удалить услугу?</h3><p>«{{deleteService.Name}}» будет удалена из состава тура вместе со всеми принадлежащими ей настройками.</p><p class="muted">Справочники, отели, рейсы и транспорт затронуты не будут.</p><div v-if="deleteChildren.length" class="delete-blocked"><strong>Удаление невозможно</strong><span>Сначала измените родителя у дочерних услуг: {{deleteChildren.map(item=>item.Name).join(', ')}}.</span></div><div class="actions"><button type="button" class="secondary" :disabled="deleting" @click="deleteService=undefined">Отмена</button><button type="button" class="danger confirm-delete" :disabled="deleting||deleteChildren.length>0" @click="removeService">{{deleting?'Удаление…':'Удалить услугу'}}</button></div></section></div>
  <TourHotelsEditor v-if="hotelService" :tour-id="tourId" :service="hotelService" @close="hotelService=undefined" @saved="load();emit('tourChanged')" />
  <TourFlightsEditor v-if="flightService" :tour-id="tourId" :service="flightService" @close="flightService=undefined" @saved="load();emit('tourChanged')" />
  <TourBusTransferEditor v-if="busTransferService" :tour-id="tourId" :service="busTransferService" @close="busTransferService=undefined" @saved="load();emit('tourChanged')" />
  <TourRailwayTransferEditor v-if="railwayTransferService" :tour-id="tourId" :service="railwayTransferService" @close="railwayTransferService=undefined" @saved="load();emit('tourChanged')" />
 </div>
</template>
<style scoped>
.compact{position:relative;margin-top:0}.compact h3{margin:0 0 5px}.add-service{position:relative}.add-service>.primary{display:flex;align-items:center;gap:8px}.add-service-menu{position:absolute;z-index:25;top:calc(100% + 8px);right:0;width:390px;padding:16px;border:1px solid #d7dfeb;border-radius:10px;background:#fff;box-shadow:0 16px 40px #20304a25}.add-service-menu>label{display:block;margin-bottom:8px;font-size:12px;font-weight:700;color:#526176}.add-service-menu>small{display:block;margin-top:9px;color:#718097}.service-columns{display:grid;grid-template-columns:minmax(260px,1fr) 94px 105px 110px minmax(290px,auto);gap:12px;padding:0 14px 8px 54px;color:#718097;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em}.service-card{grid-template-columns:28px minmax(220px,1fr) 94px 105px 110px minmax(290px,auto);transition:transform .15s,box-shadow .15s,border-color .15s}.service-card.dragging{opacity:.45}.service-card.drag-over{border-color:#3977eb;box-shadow:0 0 0 3px #3977eb1c;transform:translateY(2px)}.drag-handle{align-self:stretch;border:0;background:transparent;color:#8b98aa;cursor:grab;font-size:20px;letter-spacing:-4px}.drag-handle:active{cursor:grabbing}.service-name{min-width:0}.inline-check{display:flex;justify-content:center;align-items:center}.inline-check span{display:none}.inline-check input{width:17px;height:17px;accent-color:#286be6}.inline-check input:disabled{cursor:not-allowed}.row-actions{display:flex;justify-content:flex-end;gap:6px}.rename-backdrop{position:fixed;z-index:40;inset:0;display:grid;place-items:center;padding:24px;background:#101a2a99}.rename-dialog,.delete-dialog{width:min(480px,100%);padding:24px;border-radius:12px;background:#fff;box-shadow:0 24px 70px #101a2a42}.rename-header{display:flex;align-items:start;justify-content:space-between;margin-bottom:20px}.rename-header h3{margin:4px 0 0;font-size:22px}.delete-dialog{text-align:center}.delete-dialog h3{margin:10px 0 8px;font-size:22px}.delete-dialog p{margin:6px 0;line-height:1.5}.delete-icon{display:grid;place-items:center;width:44px;height:44px;margin:auto;border-radius:50%;background:#fff0f0;color:#b42d2d;font-size:24px;font-weight:800}.delete-blocked{display:grid;gap:5px;margin-top:16px;padding:12px;border:1px solid #ffd0d0;border-radius:7px;background:#fff1f1;color:#a12323;text-align:left;font-size:13px}.confirm-delete{background:#c83434;color:#fff}.danger:disabled{cursor:not-allowed;opacity:.5}
@media(max-width:1050px){.service-columns{display:none}.service-card{grid-template-columns:28px 1fr repeat(3,38px)}.row-actions{grid-column:2/-1;justify-content:flex-start;flex-wrap:wrap}.inline-check{position:relative}.inline-check span{display:none}}
@media(max-width:650px){.service-card{grid-template-columns:24px 1fr}.inline-check{grid-column:2;justify-content:flex-start;gap:7px}.inline-check span{display:inline}.row-actions{grid-column:2}}
</style>
